{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
for c in ['leaf_litter','slope_deg','road_dist_km','rainfall_mm','elevation_m']:
    print("==",c)
    for reg, g in df.dropna(subset=['species_richness',c]).groupby('region'):
        m = smf.ols(f'species_richness ~ {c}', data=g).fit()
        print(f"  {reg:8s} n={len(g):3d} coef={m.params[c]:7.3f} p={m.pvalues[c]:.3f}")
"}

{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
cands = ['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']
# spline (natural cubic via patsy cr) per candidate
for c in cands:
    d = df.dropna(subset=['species_richness',c]).copy()
    try:
        m = smf.ols(f'species_richness ~ cr({c}, df=4) + C(region)', data=d).fit()
        f = m.f_test(' = 0, '.join([t for t in m.params.index if t.startswith(f'cr({c}')]) + ' = 0')
        print(f"{c:16s} spline joint p={f.pvalue:.4g}")
    except Exception as e:
        print(c, e)
"}
